insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_ss_v1'
from (values
('113.20.c.1.A',3,'Which era of U.S. history came first?','["colonization", "the Civil War", "westward expansion", "Reconstruction"]'::jsonb,0,'Colonies came before independence.','original'),
('113.20.c.1.A',3,'Which era followed the American Revolution?','["Reconstruction", "the early republic and the writing of the Constitution", "colonization", "Manifest Destiny"]'::jsonb,1,'A new government was formed.','original'),
('113.20.c.1.B',3,'What happened in 1607?','["the Declaration was signed", "the Civil War began", "Jamestown was founded", "the Mayflower landed"]'::jsonb,2,'Jamestown was the first permanent English settlement.','original'),
('113.20.c.1.B',3,'What happened in 1776?','["the Constitution was signed", "the Civil War began", "Jamestown was founded", "the Declaration of Independence was adopted"]'::jsonb,3,'Independence was declared.','original'),
('113.20.c.1.B',3,'What happened in 1787?','["the Constitution was written in Philadelphia", "the War of 1812 began", "the Civil War ended", "the Mayflower arrived"]'::jsonb,0,'The Convention met in 1787.','original'),
('113.20.c.1.B',3,'In what year did the Civil War begin?','["1812", "1861", "1776", "1877"]'::jsonb,1,'It began at Fort Sumter.','original'),
('113.20.c.2.A',3,'Which was a main reason Spain explored and colonized North America?','["to build railroads", "to escape the Industrial Revolution", "to find gold and spread Catholicism", "to start factories"]'::jsonb,2,'Spain sought wealth and converts.','original'),
('113.20.c.2.A',3,'French colonists in North America were mainly interested in...','["railroads", "cotton plantations", "factories", "the fur trade"]'::jsonb,3,'Fur trapping drove New France.','original'),
('113.20.c.2.B',4,'Which colony was founded mainly for religious freedom by the Pilgrims?','["Plymouth", "New Amsterdam", "Jamestown", "Georgia"]'::jsonb,0,'Pilgrims sought to practice their faith.','original'),
('113.20.c.2.B',3,'Georgia was founded partly as...','["a religious refuge for Quakers", "a buffer against Spanish Florida and a haven for debtors", "a fur trading post", "a tobacco colony"]'::jsonb,1,'James Oglethorpe led it.','original'),
('113.20.c.2.B',3,'The Middle Colonies were known for...','["only tobacco", "Catholic missions", "religious tolerance and grain farming", "only fishing"]'::jsonb,2,'Diversity and fertile farmland.','original'),
('113.20.c.3.A',3,'Which colonial institution gave voters a voice in Virginia''s government in 1619?','["the Supreme Court", "the Senate", "Parliament", "the House of Burgesses"]'::jsonb,3,'It was the first elected assembly in English America.','original'),
('113.20.c.3.B',3,'The Mayflower Compact was important because it...','["set up self-government by agreement of the settlers", "declared independence", "created slavery", "ended taxes"]'::jsonb,0,'Settlers agreed to make laws together.','original'),
('113.20.c.3.B',4,'The Fundamental Orders of Connecticut are considered an early...','["declaration of war", "written constitution", "tax law", "trade treaty"]'::jsonb,1,'They set up a government by the people.','original'),
('113.20.c.3.C',3,'How did religion contribute to representative government in the colonies?','["churches were governed by kings", "churches banned voting", "congregations practiced self-rule and valued virtue", "religion was outlawed"]'::jsonb,2,'Town meetings and church governance taught self-rule.','original'),
('113.20.c.4.A',3,'The Proclamation of 1763 angered colonists because it...','["ended slavery", "created a navy", "raised tea taxes", "banned settlement west of the Appalachians"]'::jsonb,3,'It limited westward expansion.','original'),
('113.20.c.4.A',3,'''No taxation without representation'' protested taxes imposed by...','["Parliament", "the Continental Congress", "colonial assemblies", "state governors"]'::jsonb,0,'Colonists had no voice in Parliament.','original'),
('113.20.c.4.A',3,'The Stamp Act of 1765 taxed...','["tea only", "printed materials such as newspapers and legal documents", "ships only", "land only"]'::jsonb,1,'It sparked widespread protest.','original'),
('113.20.c.4.B',3,'Who commanded the Continental Army?','["John Hancock", "Thomas Paine", "George Washington", "Patrick Henry"]'::jsonb,2,'Washington led the army.','original'),
('113.20.c.4.C',3,'The Battles of Lexington and Concord in 1775 were the...','["last battles of the Revolution", "end of the French war", "start of the Civil War", "first battles of the Revolution"]'::jsonb,3,'''The shot heard round the world.''','original'),
('113.20.c.4.C',4,'Which battle in 1777 convinced France to ally with the Americans?','["Saratoga", "Gettysburg", "Lexington", "Bunker Hill"]'::jsonb,0,'Saratoga was a turning point.','original'),
('113.20.c.4.D',4,'The Great Compromise at the Constitutional Convention created...','["a weak central government", "a two-house Congress with equal representation in the Senate and population-based representation in the House", "a single-house Congress", "a king"]'::jsonb,1,'It balanced large and small states.','original'),
('113.20.c.4.D',4,'The Three-Fifths Compromise counted each enslaved person as...','["half a person", "a full person", "three-fifths of a person for representation and taxes", "no person"]'::jsonb,2,'It increased the South''s representation.','original'),
('113.20.c.5.A',3,'A major problem for the new republic under the Articles of Confederation was...','["no states", "an overly strong president", "too much federal power", "paying war debts and keeping order without strong central power"]'::jsonb,3,'The central government was weak.','original'),
('113.20.c.5.B',3,'The Fugitive Slave Act of 1793 required that...','["escaped enslaved people be returned to their owners", "enslaved people be freed", "free Blacks be given land", "slavery be banned in the North"]'::jsonb,0,'It strengthened slaveholders'' claims.','original'),
('113.20.c.5.C',4,'Alexander Hamilton wanted a national bank and protective tariffs to...','["abolish taxes", "strengthen the economy and credit of the new nation", "weaken the government", "end trade"]'::jsonb,1,'He promoted manufacturing and finance.','original'),
('113.20.c.5.D',3,'The first two political parties were the Federalists and the...','["Know-Nothings", "Whigs", "Democratic-Republicans", "Republicans"]'::jsonb,2,'Jefferson led the Democratic-Republicans.','original'),
('113.20.c.5.E',3,'A major cause of the War of 1812 was...','["the Mexican War", "the cotton gin", "the Louisiana Purchase", "British impressment of American sailors and interference with trade"]'::jsonb,3,'Britain seized sailors and ships.','original'),
('113.20.c.5.E',4,'A major effect of the War of 1812 was...','["a surge of American nationalism and growth in manufacturing", "British rule restored", "the end of the Constitution", "the loss of the Midwest"]'::jsonb,0,'The war boosted national pride.','original'),
('113.20.c.5.F',3,'The Monroe Doctrine warned European nations not to...','["trade with America", "colonize or interfere in the Western Hemisphere", "visit the U.S.", "fight in Asia"]'::jsonb,1,'It declared a sphere of U.S. influence.','original'),
('113.20.c.5.G',3,'Andrew Jackson''s election in 1828 reflected the expansion of...','["slavery''s end", "voting for women", "suffrage to more white men without property", "the powers of the king"]'::jsonb,2,'Voting rights widened.','original'),
('113.20.c.5.H',4,'The Indian Removal Act led to the forced relocation of the Cherokee on the...','["Santa Fe Trail", "Oregon Trail", "Chisholm Trail", "Trail of Tears"]'::jsonb,3,'Thousands died on the forced march.','original'),
('113.20.c.6.A',3,'The Northwest Ordinance of 1787 established...','["a process for new territories to become states and banned slavery there", "a state religion", "a new tax", "a national bank"]'::jsonb,0,'It guided orderly expansion.','original'),
('113.20.c.6.B',3,'The Louisiana Purchase of 1803 doubled the size of the U.S. when it was bought from...','["Britain", "France", "Spain", "Mexico"]'::jsonb,1,'President Jefferson made the deal.','original'),
('113.20.c.6.B',3,'Manifest Destiny was the belief that the United States was meant to...','["stay small", "avoid territory", "expand across the continent", "give up land"]'::jsonb,2,'A popular idea in the 1840s.','original'),
('113.20.c.6.C',3,'The U.S.-Mexican War ended with the Treaty of Guadalupe Hidalgo, which gave the U.S....','["Alaska", "Florida", "Texas only", "California and much of the Southwest"]'::jsonb,3,'The Mexican Cession.','original'),
('113.20.c.7.A',4,'Northern manufacturers supported high protective tariffs, but Southern planters opposed them because...','["tariffs raised prices of goods they bought and hurt exports", "they opposed trade", "they wanted slavery abolished", "they wanted more factories"]'::jsonb,0,'Tariffs hurt the agricultural South.','original'),
('113.20.c.7.B',4,'Which best compares enslaved people and free Blacks before the Civil War?','["both had full citizenship", "free Blacks had more freedom but still faced discrimination and limited rights", "free Blacks owned plantations", "enslaved people could vote"]'::jsonb,1,'Freedom was limited by law and custom.','original'),
('113.20.c.7.C',3,'The Fugitive Slave Act of 1850 made it a crime to...','["move west", "print newspapers", "help runaway enslaved people and required citizens to assist capture", "buy land"]'::jsonb,2,'Northerners were forced to cooperate.','original'),
('113.20.c.7.D',3,'Slavery was most important to the economy of which section?','["the Midwest", "the Northeast", "New England", "the South"]'::jsonb,3,'Plantations relied on enslaved labor.','original'),
('113.20.c.7.E',3,'The Missouri Compromise of 1820 admitted Missouri as a slave state and...','["Maine as a free state", "Kansas as a slave state", "Texas as a slave state", "California as a free state"]'::jsonb,0,'It kept the balance in the Senate.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_ss_v1'
from (values
('113.20.c.7.E',4,'The Kansas-Nebraska Act of 1854 allowed settlers to decide on slavery through...','["Supreme Court order", "popular sovereignty", "a presidential decision", "a national vote"]'::jsonb,1,'It led to ''Bleeding Kansas.''','original'),
('113.20.c.8.A',3,'Who was president of the Confederate States?','["Abraham Lincoln", "Ulysses S. Grant", "Jefferson Davis", "Robert E. Lee"]'::jsonb,2,'Davis led the Confederacy.','original'),
('113.20.c.8.A',3,'Who led Union forces to victory and later became president?','["Robert E. Lee", "Jefferson Davis", "Stonewall Jackson", "Ulysses S. Grant"]'::jsonb,3,'Grant accepted Lee''s surrender.','original'),
('113.20.c.8.B',3,'What issue was central to causing sectionalism and secession?','["the expansion of slavery", "railroad schedules", "fishing rights", "the telegraph"]'::jsonb,0,'Disagreement over slavery divided the nation.','original'),
('113.20.c.8.C',3,'The Civil War began with the firing on...','["Gettysburg", "Fort Sumter", "Appomattox", "Harpers Ferry"]'::jsonb,1,'Confederates fired in April 1861.','original'),
('113.20.c.8.C',3,'The Battle of Gettysburg is considered a turning point because...','["it was a Confederate victory that won independence", "it ended slavery by itself", "it ended Lee''s invasion of the North and weakened the Confederacy", "it ended the war immediately"]'::jsonb,2,'Union victory in July 1863.','original'),
('113.20.c.8.C',4,'Lee surrendered to Grant at...','["Fort Sumter", "Antietam", "Vicksburg", "Appomattox Court House"]'::jsonb,3,'The war ended in April 1865.','original'),
('113.20.c.8.D',4,'In the Gettysburg Address, Lincoln emphasized that the nation was dedicated to...','["liberty and equality and government of the people", "secession", "kings", "isolation"]'::jsonb,0,'He tied the war to the Declaration.','original'),
('113.20.c.9.A',3,'The Freedmen''s Bureau was created to help...','["plantation owners", "formerly enslaved people with education, food and legal aid", "factory owners", "railroad builders"]'::jsonb,1,'It aided freedpeople.','original'),
('113.20.c.9.B',4,'Hiram Revels was the first...','["Confederate general", "president", "African American U.S. senator", "Chief Justice"]'::jsonb,2,'He represented Mississippi.','original'),
('113.20.c.9.C',4,'What was one problem of Reconstruction in the South?','["lack of rain", "lack of cotton", "too many railroads", "violence by groups such as the Ku Klux Klan against Black citizens"]'::jsonb,3,'White supremacist violence undermined rights.','original'),
('113.20.c.9.C',3,'The Compromise of 1877 ended Reconstruction by...','["removing federal troops from the South", "freeing the enslaved", "giving land to freedpeople", "abolishing the Senate"]'::jsonb,0,'Federal troops left.','original'),
('113.20.c.10.A',3,'Which river was the western boundary of the U.S. after the Revolution?','["the Colorado River", "the Mississippi River", "the Columbia River", "the Rio Grande"]'::jsonb,1,'The 1783 treaty set it.','original'),
('113.20.c.10.B',3,'The Northeast was known for...','["mining gold", "cattle ranches", "factories and busy ports", "rice plantations"]'::jsonb,2,'Industry grew there.','original'),
('113.20.c.10.C',4,'Why was the Mississippi River so important to the early U.S. economy?','["it blocked travel", "it was too shallow", "it was a desert", "it provided a route to move goods to market"]'::jsonb,3,'Rivers carried trade.','original'),
('113.20.c.11.A',3,'Why did most early colonial towns grow near rivers and harbors?','["water provided transportation and trade", "harbors were frozen", "rivers were desert", "rivers blocked trade"]'::jsonb,0,'Physical features shaped settlement.','original'),
('113.20.c.11.B',4,'A negative consequence of clearing forests for farmland was...','["more forests", "soil erosion and loss of habitat", "more rainfall", "fewer farms"]'::jsonb,1,'Human modification can harm the environment.','original'),
('113.20.c.12.A',3,'Before the Civil War, the Northeast''s economy relied mainly on...','["plantation cotton", "ranching", "manufacturing and trade", "mining"]'::jsonb,2,'Industry dominated the North.','original'),
('113.20.c.12.B',4,'The plantation system in the South developed because of demand for cash crops such as...','["steel and coal", "fish and furs", "wheat and oats", "cotton and tobacco"]'::jsonb,3,'Cash crops needed large labor.','original'),
('113.20.c.12.C',4,'A cause of economic differences among regions was...','["differences in climate, resources and labor systems", "equal factories", "the same crops", "identical land"]'::jsonb,0,'Geography shaped economies.','original'),
('113.20.c.13.A',4,'An economic effect of the War of 1812 was...','["loss of trade forever", "growth in American manufacturing because British goods were scarce", "a collapse of all industry", "higher tariffs on U.S. goods"]'::jsonb,1,'Americans made more at home.','original'),
('113.20.c.13.B',3,'What helped cause rapid industrialization in the U.S.?','["no inventions", "lack of resources", "new machines, capital and available workers", "no cities"]'::jsonb,2,'Factories needed machines and labor.','original'),
('113.20.c.14.A',3,'Which belief helped free enterprise develop in the new nation?','["no trade", "government owns all land", "fixed prices", "private property and the right to make a profit"]'::jsonb,3,'Individual rights supported markets.','original'),
('113.20.c.14.B',3,'A benefit of free enterprise is...','["consumers can choose among competing goods", "government set prices", "no competition", "a single seller"]'::jsonb,0,'Competition benefits buyers.','original'),
('113.20.c.15.A',3,'The Magna Carta influenced the Constitution by establishing that...','["there are no courts", "even the king must obey the law", "kings are above law", "taxes cannot exist"]'::jsonb,1,'It limited power.','original'),
('113.20.c.15.B',3,'A weakness of the Articles of Confederation was that Congress could not...','["elect a president", "sign treaties", "tax or regulate trade", "declare independence"]'::jsonb,2,'Congress was weak.','original'),
('113.20.c.15.C',3,'A grievance listed in the Declaration of Independence was that the king...','["banned slavery", "gave colonists too much freedom", "created a Congress", "imposed taxes without consent"]'::jsonb,3,'Colonists objected to taxation.','original'),
('113.20.c.15.D',4,'The separation of powers in the Constitution means...','["power is divided among three branches", "the president rules alone", "states have no power", "Congress can do anything"]'::jsonb,0,'Legislative, executive and judicial.','original'),
('113.20.c.15.E',3,'Montesquieu influenced the Constitution with his idea of...','["a state church", "separating government powers", "a divine king", "no laws"]'::jsonb,1,'He inspired checks and balances.','original'),
('113.20.c.16.A',3,'Amendments to the Constitution are made to...','["erase it", "end the government", "change or add to the Constitution as needs change", "elect a king"]'::jsonb,2,'Amendments adapt the document.','original'),
('113.20.c.16.B',3,'The 13th Amendment...','["gave women the vote", "ended Prohibition", "created income tax", "abolished slavery"]'::jsonb,3,'It ended slavery in 1865.','original'),
('113.20.c.16.B',3,'The 14th Amendment granted...','["citizenship and equal protection to all persons born or naturalized in the U.S.", "an income tax", "voting to women", "a two-term limit"]'::jsonb,0,'It defined citizenship.','original'),
('113.20.c.16.B',3,'The 15th Amendment protected the right to vote regardless of...','["age", "race", "wealth", "religion"]'::jsonb,1,'It targeted racial barriers to voting.','original'),
('113.20.c.17.A',3,'Federalists such as Alexander Hamilton supported...','["a monarchy", "abolishing the states", "a strong national government and ratifying the Constitution", "no constitution"]'::jsonb,2,'They supported ratification.','original'),
('113.20.c.17.A',3,'Anti-Federalists feared the Constitution would...','["eliminate states", "end elections", "limit trade", "give too much power to the national government without a bill of rights"]'::jsonb,3,'They demanded a Bill of Rights.','original'),
('113.20.c.17.B',4,'The nullification idea claimed that states could...','["reject federal laws they believed unconstitutional", "declare war on Canada", "elect the president", "make federal laws"]'::jsonb,0,'John C. Calhoun promoted it.','original'),
('113.20.c.18.A',3,'Judicial review is the power of courts to...','["write laws", "decide whether laws are constitutional", "elect judges", "veto bills"]'::jsonb,1,'It was established in Marbury v. Madison.','original'),
('113.20.c.18.B',4,'McCulloch v. Maryland (1819) upheld the power of...','["the states to tax the bank", "the king", "the federal government over the states", "state governments over federal law"]'::jsonb,2,'It affirmed implied powers.','original'),
('113.20.c.18.C',4,'Dred Scott v. Sandford (1857) ruled that...','["free Blacks were citizens", "Missouri was free", "slavery was abolished", "enslaved people were not citizens and Congress could not ban slavery in the territories"]'::jsonb,3,'It inflamed sectional tensions.','original'),
('113.20.c.19.A',3,'Unalienable rights are rights...','["that cannot be taken away", "that can be bought", "given by a king", "that depend on wealth"]'::jsonb,0,'Life, liberty and the pursuit of happiness.','original'),
('113.20.c.19.B',3,'The First Amendment guarantees freedom of...','["only taxes", "religion, speech, press, assembly and petition", "only travel", "only the draft"]'::jsonb,1,'It protects expression.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
