from (values
('113.20.c.19.C',3,'Which is an example of responsible citizenship?','["breaking rules", "avoiding the news", "obeying laws and staying informed", "ignoring elections"]'::jsonb,2,'Citizens should participate.','original'),
('113.20.c.20.A',4,'The Founding Fathers are often called models of civic virtue because they...','["only sought wealth", "avoided public service", "ignored laws", "put the common good ahead of self-interest"]'::jsonb,3,'They sacrificed for the nation.','original'),
('113.20.c.20.B',4,'Henry David Thoreau''s civil disobedience meant...','["peacefully refusing to obey a law believed to be unjust", "violent revolt", "obeying all laws", "fleeing the country"]'::jsonb,0,'He went to jail rather than pay a tax.','original'),
('113.20.c.21.A',3,'Why did Federalists and Democratic-Republicans disagree?','["they supported kings", "they had different views on the role of the national government", "they wanted the same things", "they never debated"]'::jsonb,1,'Parties form around beliefs.','original'),
('113.20.c.21.B',3,'A free press in a constitutional republic helps citizens...','["avoid laws", "elect kings", "get information and hold leaders accountable", "avoid news"]'::jsonb,2,'Free press protects democracy.','original'),
('113.20.c.21.C',3,'The Missouri Compromise is an example of a...','["treaty with France", "war", "tax law", "compromise that resolved a conflict"]'::jsonb,3,'Congress balanced slave and free states.','original'),
('113.20.c.22.A',3,'Abraham Lincoln showed leadership during the Civil War by...','["preserving the Union and issuing the Emancipation Proclamation", "surrendering to the Confederacy", "dissolving Congress", "ending the Constitution"]'::jsonb,0,'He led the Union.','original'),
('113.20.c.22.B',3,'Frederick Douglass was a former slave who became a leading...','["Confederate general", "abolitionist writer and speaker", "king''s governor", "plantation owner"]'::jsonb,1,'He fought for abolition.','original'),
('113.20.c.23.A',3,'Many Irish immigrants came to the U.S. in the 1840s to escape...','["the Civil War", "the Dust Bowl", "the potato famine", "the Cold War"]'::jsonb,2,'Crop failure drove migration.','original'),
('113.20.c.23.B',4,'Rapid urbanization led to conflict in cities partly because of...','["lack of people", "no factories", "no immigrants", "competition for jobs and religious and cultural differences"]'::jsonb,3,'Cities were crowded.','original'),
('113.20.c.23.C',3,'Which helped immigrants adapt to life in a new country?','["community organizations and shared languages", "closing schools", "isolation", "banning newspapers"]'::jsonb,0,'Support networks helped.','original'),
('113.20.c.23.D',3,'German immigrants contributed to American life by...','["inventing the telegraph", "farming, brewing and founding schools and newspapers", "ending slavery alone", "building pyramids"]'::jsonb,1,'They enriched American culture.','original'),
('113.20.c.23.E',3,'Which woman was a leader of the women''s suffrage movement and helped organize the Seneca Falls Convention?','["Sacagawea", "Dolley Madison", "Elizabeth Cady Stanton", "Betsy Ross"]'::jsonb,2,'Seneca Falls took place in 1848.','original'),
('113.20.c.24.A',3,'William Lloyd Garrison published an antislavery newspaper called...','["The Federalist", "The Tribune", "The Gazette", "The Liberator"]'::jsonb,3,'He called for immediate abolition.','original'),
('113.20.c.24.B',3,'Horace Mann is known for promoting...','["public education reform", "cotton farming", "the telegraph", "railroad building"]'::jsonb,0,'He championed common schools.','original'),
('113.20.c.24.B',4,'The temperance movement sought to...','["end slavery", "reduce or ban the use of alcohol", "expand voting", "build railroads"]'::jsonb,1,'Reformers viewed alcohol as harmful.','original'),
('113.20.c.25.A',3,'The First Amendment protects religious freedom by...','["requiring one church", "banning all religion", "barring Congress from establishing a state religion", "taxing churches"]'::jsonb,2,'Religion is free from government control.','original'),
('113.20.c.25.B',4,'The Second Great Awakening encouraged many people to join...','["the Confederacy only", "the king''s court", "the military only", "reform movements such as abolition and temperance"]'::jsonb,3,'Religious revival fueled reform.','original'),
('113.20.c.25.C',3,'Religious freedom in America attracted immigrants such as...','["Quakers and Jews seeking to worship without persecution", "people who banned worship", "only soldiers", "people who wanted a king"]'::jsonb,0,'Freedom drew many groups.','original'),
('113.20.c.26.A',3,'The Hudson River School painters celebrated...','["foreign kings", "the beauty of the American landscape", "industrial machines", "wartime battles"]'::jsonb,1,'A group of 19th-century landscape painters.','original'),
('113.20.c.26.A',4,'Which writer wrote ''Uncle Tom''s Cabin,'' influencing attitudes about slavery?','["Edgar Allan Poe", "Louisa May Alcott", "Harriet Beecher Stowe", "Emily Dickinson"]'::jsonb,2,'The novel stirred antislavery feeling.','original'),
('113.20.c.26.B',4,'Spirituals sung by enslaved people reflect...','["royal court life", "only factory work", "wealth", "faith, hope and coded messages about freedom"]'::jsonb,3,'Music expressed resilience.','original'),
('113.20.c.27.A',3,'The steamboat changed transportation by...','["making river travel faster and upstream trade possible", "ending trade", "closing rivers", "slowing travel"]'::jsonb,0,'Robert Fulton''s steamboat improved shipping.','original'),
('113.20.c.27.A',3,'The cotton gin increased the demand for enslaved labor because it...','["freed workers", "made growing cotton far more profitable", "abolished cotton", "ended plantations"]'::jsonb,1,'Eli Whitney''s invention boosted cotton.','original'),
('113.20.c.27.B',4,'The use of interchangeable parts changed manufacturing by...','["making hand tools required", "stopping factories", "allowing goods to be made faster and cheaper", "ending jobs"]'::jsonb,2,'Mass production grew.','original'),
('113.20.c.27.C',4,'The railroad helped economic growth by...','["ending farming", "stopping towns", "slowing trade", "linking markets and speeding the movement of goods"]'::jsonb,3,'Rail networks connected regions.','original'),
('113.20.c.28.A',3,'The telegraph changed communication by...','["sending messages quickly over long distances", "banning letters", "slowing mail", "ending newspapers"]'::jsonb,0,'Samuel Morse''s invention sped news.','original'),
('113.20.c.28.B',3,'Industrialization changed life in the United States by...','["ending cities", "moving many people from farms to factory jobs in cities", "ending trade", "stopping immigration"]'::jsonb,1,'Workers moved to cities.','original'),
