('113.20.c.29.A',3,'A modern biography of Abraham Lincoln is a...','["primary source", "diary", "speech he gave", "secondary source"]'::jsonb,3,'Written long after.','original'),
('113.20.c.29.B',3,'Which events are in the correct order?','["Declaration of Independence, Constitution, Civil War", "Constitution, Civil War, Declaration of Independence", "Civil War, Constitution, Declaration of Independence", "Civil War, Declaration of Independence, Constitution"]'::jsonb,0,'Chronological order.','original'),
('113.20.c.29.C',3,'Which visual best shows the number of free and slave states over time?','["a portrait", "a line graph or chart", "a recipe", "a poem"]'::jsonb,1,'Charts show change over time.','original'),
('113.20.c.29.D',4,'A newspaper from the South and a newspaper from the North describe the same election differently. This shows...','["identical biases", "different alphabets", "different points of view", "no opinion"]'::jsonb,2,'Perspective shapes reporting.','original'),
